import{_ as r}from"./chunks/circle-plus.8rbASrIO.js";import{_ as o}from"./chunks/plus.s75sSGIW.js";import{_ as s,c as a,o as d,a7 as e}from"./chunks/framework.DPTpzYjp.js";const i="/ruidu-docs/images/orbitcontrol/user-guide/missions-page-list.png",n="/ruidu-docs/images/orbitcontrol/user-guide/missions-form-path.png",l="/ruidu-docs/images/orbitcontrol/user-guide/missions-form-path-waypoint.gif",q=JSON.parse('{"title":"任务","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/missions.md","filePath":"orbitcontrol/user-guide/missions.md"}'),g={name:"orbitcontrol/user-guide/missions.md"};function h(c,t,p,m,u,b){return d(),a("div",null,t[0]||(t[0]=[e('<h1 id="任务" tabindex="-1">任务 <a class="header-anchor" href="#任务" aria-label="Permalink to &quot;任务&quot;">​</a></h1><p>「任务」定义设备的一次完整作业：设备按顺序经过一系列<strong>航点</strong>，并在航点上执行<strong>动作</strong>（拍照、录像、播报语音等）。任务创建后，可在 <a href="./live-control.html">设备控制</a> 中手动执行，也可以交给 <a href="./schedules.html">计划</a> 定时调度或 <a href="./flows.html">自动化流程</a> 触发执行。</p><p>平台支持两类任务：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td><strong>路径任务</strong></td><td>逐个航点依次巡行，每个航点可配置动作</td><td>可用</td></tr><tr><td><strong>网格任务</strong></td><td>覆盖式网格巡行（适用于区域覆盖拍摄等场景）</td><td>建设中</td></tr></tbody></table><h2 id="任务列表" tabindex="-1">任务列表 <a class="header-anchor" href="#任务列表" aria-label="Permalink to &quot;任务列表&quot;">​</a></h2><p>左侧为任务列表，支持按名称搜索、按站点筛选。点击右上角 <img src="'+r+'" alt=""> 选择任务类型开始创建。</p><p><img src="'+i+'" alt=""></p><p>任务卡片显示任务类型图标、名称、所属站点和最后更新时间，可进行<strong>编辑</strong>和<strong>删除</strong>（删除需二次确认）。</p><h2 id="创建路径任务" tabindex="-1">创建路径任务 <a class="header-anchor" href="#创建路径任务" aria-label="Permalink to &quot;创建路径任务&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>新任务需<strong>先保存基础信息</strong>（名称、站点、任务配置），再进入编辑绘制航点。</p></div><h3 id="第一步-保存基础信息" tabindex="-1">第一步：保存基础信息 <a class="header-anchor" href="#第一步-保存基础信息" aria-label="Permalink to &quot;第一步：保存基础信息&quot;">​</a></h3><p>点击「路径任务」进入编辑器，填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>任务名称</td><td>20 个字以内</td></tr><tr><td>选择站点</td><td>任务归属的站点，决定可用的地图</td></tr><tr><td>巡航速度</td><td>设备巡行的速度（m/s），最小 1</td></tr><tr><td>结束动作</td><td>任务完成后的行为：<strong>返航</strong> / <strong>原地等待</strong> / <strong>回到第一个航点</strong></td></tr></tbody></table><p><img src="'+n+'" alt="" class="w-1/2"></p><h3 id="第二步-绘制航点" tabindex="-1">第二步：绘制航点 <a class="header-anchor" href="#第二步-绘制航点" aria-label="Permalink to &quot;第二步：绘制航点&quot;">​</a></h3><p>保存后从任务列表重新进入编辑，切换到「路径配置」页签，点击 <img src="'+o+'" alt=""> 进入加点模式，在地图上依次点击放置航点：</p><ul><li>点击地图上的<strong>路网节点</strong>可直接吸附节点位置</li><li>点选完成后点击「结束」退出加点模式</li><li>通过 <code>‹ ›</code> 按钮（或点击地图上的航点）在航点间切换，当前航点高亮</li><li>工具栏还提供<strong>定位</strong>（地图视角跳到当前航点）和<strong>删除</strong>（移除当前航点）</li></ul><p>站点有多张地图时，可通过地图控件切换地图，分别在不同地图上添加航点（跨地图任务）；选中其他地图上的航点时会自动切换过去。</p><h3 id="航点动作" tabindex="-1">航点动作 <a class="header-anchor" href="#航点动作" aria-label="Permalink to &quot;航点动作&quot;">​</a></h3><p>选中航点后，在「执行动作」中添加该航点到达后执行的动作，动作按顺序执行，可拖拽调整顺序：</p><table tabindex="0"><thead><tr><th>动作</th><th>配置项</th></tr></thead><tbody><tr><td><strong>等待</strong></td><td>等待时长（秒），0 表示无限等待</td></tr><tr><td><strong>云台记忆</strong></td><td>云台姿态（Yaw/Pitch/Zoom/Focus）；可从在线设备<strong>一键读取当前云台状态</strong></td></tr><tr><td><strong>拍照</strong></td><td>拍照数量（1~10 张）、拍照间隔（秒，0 表示仅拍 1 张）</td></tr><tr><td><strong>录像</strong></td><td>录制时长（秒）</td></tr><tr><td><strong>语音播报</strong></td><td>来源二选一：<strong>语音库</strong>（引用<a href="./voices.html">语音库</a>中生成的语音）或<strong>实时文本</strong>（设备端 TTS 播报，需设备支持）；可设置音量（0-100）</td></tr><tr><td><strong>充电</strong></td><td>目标电量（达到后自动停止充电），或勾选持续充电</td></tr></tbody></table><p><img src="'+l+'" alt=""></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>「云台记忆」的读取功能：点击动作卡片上的读取按钮，选择站点内在线设备，平台读取该设备当前云台姿态并填入动作。</p></div>',23)]))}const x=s(g,[["render",h]]);export{q as __pageData,x as default};
